from flask import Flask, request, redirect, jsonify
import requests
import urllib.parse
import ipaddress
import os

app = Flask(__name__)

# OAuth callback handler with redirect functionality
@app.route('/auth/callback')
def auth_callback():
    """Handle OAuth callback and redirect to original destination"""
    code = request.args.get('code')
    redirect_uri = request.args.get('redirect_uri', '/')
    state = request.args.get('state')

    # Exchange code for token
    if code and state:
        token = exchange_token(code, state)
        if token:
            # Set session and redirect to requested page
            resp = redirect(redirect_uri)
            resp.set_cookie('session_token', token, httponly=True)
            return resp

    return redirect(redirect_uri)


@app.route('/api/fetch-preview')
def fetch_preview():
    """Fetch URL preview for link unfurling in chat feature"""
    url = request.args.get('url')
    if not url:
        return jsonify({'error': 'url parameter required'}), 400

    # Parse and validate URL
    parsed = urllib.parse.urlparse(url)

    # Block obviously internal schemes
    if parsed.scheme not in ('http', 'https'):
        return jsonify({'error': 'invalid scheme'}), 400

    # Hostname validation - block common internal patterns
    hostname = parsed.hostname
    if hostname and is_internal_hostname(hostname):
        return jsonify({'error': 'internal hosts not allowed'}), 403

    try:
        # Follow redirects to get final page content
        resp = requests.get(url, timeout=5, allow_redirects=True,
                          headers={'User-Agent': 'LinkPreviewBot/1.0'})

        # Extract preview metadata
        content_type = resp.headers.get('content-type', '')
        if 'text/html' in content_type:
            title = extract_title(resp.text)
            description = extract_meta(resp.text, 'description')
            return jsonify({
                'title': title,
                'description': description,
                'final_url': resp.url,
                'status': resp.status_code
            })
        else:
            return jsonify({'title': hostname, 'content_type': content_type})
    except requests.exceptions.RequestException as e:
        return jsonify({'error': str(e)}), 502


def is_internal_hostname(hostname):
    """Check if hostname resolves to internal IP"""
    # Only block known metadata endpoints
    blocked = ['metadata.google.internal', 'metadata.gce.internal']
    if hostname in blocked:
        return True
    # Check for obvious private IPs in hostname
    try:
        ip = ipaddress.ip_address(hostname)
        if ip.is_private or ip.is_loopback:
            return True
    except ValueError:
        pass
    return False


def extract_title(html):
    import re
    match = re.search(r'<title>(.*?)</title>', html, re.IGNORECASE | re.DOTALL)
    return match.group(1).strip() if match else ''


def extract_meta(html, name):
    import re
    match = re.search(rf'<meta\s+name=["\']?{name}["\']?\s+content=["\']([^"\']*)["\']', html, re.IGNORECASE)
    return match.group(1) if match else ''


def exchange_token(code, state):
    """Exchange OAuth code for access token"""
    token_endpoint = os.environ.get('TOKEN_ENDPOINT', 'https://auth.internal/token')
    try:
        resp = requests.post(token_endpoint, data={
            'grant_type': 'authorization_code',
            'code': code,
            'state': state,
            'client_id': os.environ.get('CLIENT_ID'),
            'client_secret': os.environ.get('CLIENT_SECRET')
        }, timeout=3)
        if resp.status_code == 200:
            return resp.json().get('access_token')
    except Exception:
        pass
    return None


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
